mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT '0' AS CHK, , (SELECT CD_NM FROM TB_CMM_CODE WHERE GRP_CD = 'DLV_STAT' AND CD = D.DLV_STAT) AS DLV_STAT_NM, O.MBR_ID, O.ORD_STAT, O.RCV_NM, O.RCV_HP, O.RCV_ADDR, TO_CHAR(O.ORD_DT, 'YYYYMMDD') AS ORD_DT, (SELECT COUNT(*) FROM TB_ORD_ITEM I WHERE I.ORD_NO = D.ORD_NO AND I.ITEM_STAT = 'N') AS ITEM_CNT FROM TB_DLV D JOIN TB_ORD O ON O.ORD_NO = D.ORD_NO
AND D.DLV_STAT = #{DLV_STAT}
AND D.DLV_STAT IN ('R', 'S')
AND O.ORD_DT >= TO_DATE(#{FROM_YMD}, 'YYYYMMDD') AND O.ORD_DT < TO_DATE(#{TO_YMD}, 'YYYYMMDD') + 1 AND D.CARRIER_CD = #{CARRIER_CD} AND D.ORD_NO = #{ORD_NO} AND D.INVC_NO = #{INVC_NO} AND D.ISLAND_YN = #{ISLAND_YN}
ORDER BY O.ORD_DT, D.DLV_NO ) A WHERE ROWNUM <= 1000 )

SELECT 
  FROM TB_DLV D
 WHERE D.DLV_NO = #{dlvNo}

SELECT 
  FROM TB_DLV D
 WHERE D.ORD_NO = #{ordNo}
